use clap::{Parser, Subcommand, ValueEnum};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::env;
use std::fs::{self, File};
use std::io::{BufRead, BufReader, Write};
use std::path::{Path, PathBuf};
use std::process;
use std::time::{SystemTime, UNIX_EPOCH};
use std::hash::{Hash, Hasher};

const VERSION: &str = "0.9.9";
const AUTHOR: &str = "Ajeet D'Souza <98ajeet@gmail.com>";
const URL: &str = "https://github.com/ajeetdsouza/zoxide";

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Entry {
    path: String,
    score: f64,
    last_accessed: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Database {
    entries: HashMap<String, Entry>,
}

#[derive(Debug, Parser)]
#[command(name = "zoxide")]
#[command(author = AUTHOR)]
#[command(version = VERSION)]
#[command(about = "A smarter cd command for your terminal", long_about = None)]
struct Cli {
    #[command(subcommand)]
    command: Option<Commands>,

    #[arg(short, long, action = clap::ArgAction::Help)]
    help: bool,

    #[arg(short, long, action = clap::ArgAction::Version)]
    version: bool,
}

#[derive(Debug, Subcommand)]
enum Commands {
    Add {
        #[arg(short, long)]
        score: Option<f64>,
        paths: Vec<String>,
    },
    Edit,
    Import {
        #[arg(long, value_enum)]
        from: ImportFrom,
        path: String,
        #[arg(long)]
        merge: bool,
    },
    Init {
        #[arg(value_enum)]
        shell: Shell,
        #[arg(long)]
        no_cmd: bool,
        #[arg(long, default_value = "z")]
        cmd: String,
        #[arg(long, default_value = "pwd")]
        hook: Hook,
    },
    Query {
        #[arg(short, long)]
        all: bool,
        #[arg(short, long)]
        interactive: bool,
        #[arg(short, long)]
        list: bool,
        #[arg(short, long)]
        score: bool,
        #[arg(long)]
        exclude: Option<String>,
        #[arg(long)]
        base_dir: Option<String>,
        keywords: Vec<String>,
    },
    Remove {
        paths: Vec<String>,
    },
}

#[derive(Debug, Clone, Copy, ValueEnum)]
enum ImportFrom {
    Autojump,
    Z,
}

#[derive(Debug, Clone, Copy, ValueEnum)]
enum Shell {
    Bash,
    Elvish,
    Fish,
    Nushell,
    Posix,
    Powershell,
    Tcsh,
    Xonsh,
    Zsh,
}

#[derive(Debug, Clone, Copy, ValueEnum)]
enum Hook {
    None,
    Prompt,
    Pwd,
}

fn get_data_dir() -> PathBuf {
    if let Ok(data_dir) = env::var("_ZO_DATA_DIR") {
        return PathBuf::from(data_dir);
    }
    let home = env::var("HOME").unwrap_or_else(|_| "/".to_string());
    let xdg_data_home = env::var("XDG_DATA_HOME").unwrap_or_else(|_| format!("{}/.local/share", home));
    if cfg!(target_os = "macos") {
        format!("{}/Library/Application Support", home).into()
    } else if cfg!(target_os = "windows") {
        format!("{}/Local Settings/Application Data", home).into()
    } else {
        xdg_data_home.into()
    }
}

fn get_db_path() -> PathBuf {
    get_data_dir().join("zoxide.db")
}

fn load_db() -> Database {
    let db_path = get_db_path();
    if !db_path.exists() {
        return Database { entries: HashMap::new() };
    }
    let file = File::open(&db_path).expect("Failed to open database");
    let reader = BufReader::new(file);
    let content: String = reader.lines().collect::<Result<Vec<_>, _>>().unwrap_or_default().join("\n");
    if content.is_empty() {
        return Database { entries: HashMap::new() };
    }
    serde_json::from_str(&content).unwrap_or_else(|_| Database { entries: HashMap::new() })
}

fn save_db(db: &Database) {
    let db_path = get_db_path();
    let content = serde_json::to_string_pretty(db).unwrap();
    let mut file = File::create(&db_path).expect("Failed to create database");
    file.write_all(content.as_bytes()).expect("Failed to write database");
}

fn get_timestamp() -> u64 {
    SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_else(|_| std::time::Duration::from_secs(0)).as_secs()
}

fn get_score(entry: &Entry) -> f64 {
    let now = get_timestamp();
    let age = now - entry.last_accessed;
    entry.score * (1.0 + 0.0001 * age)
}

fn normalize_path(path: &str) -> String {
    let path = path.trim();
    if path.starts_with('/') {
        path.to_string()
    } else {
        format!("/{}", path)
    }
}

fn canonicalize_path(path: &str) -> String {
    let path = Path::new(path);
    if path.is_absolute() {
        path.to_string_lossy().to_string()
    } else {
        let cwd = env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
        cwd.join(path).to_string_lossy().to_string()
    }
}

fn is_directory(path: &str) -> bool {
    let path = Path::new(path);
    if path.is_absolute() {
        path.is_dir()
    } else {
        let cwd = env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
        cwd.join(path).is_dir()
    }
}
