fn main() {
    let args: Vec<String> = env::args().collect();
    let cli = Cli::parse_from(&args);

    match cli.command {
        Some(Commands::Add { score, paths }) => {
            for path in paths {
                let normalized = normalize_path(&path);
                let canonical = canonicalize_path(&normalized);
                if !is_directory(&canonical) {
                    eprintln!("{} is not a directory", canonical);
                    process::exit(1);
                }
                let db = load_db();
                let entry = db.entries.get(&canonical).cloned().unwrap_or_else(|| {
                    Entry {
                        path: canonical.clone(),
                        score: 0.0,
                        last_accessed: get_timestamp(),
                    }
                });
                let new_score = score.unwrap_or_else(|| get_score(&entry));
                let mut new_entry = entry;
                new_entry.score = new_score;
                new_entry.last_accessed = get_timestamp();
                db.entries.insert(canonical, new_entry);
                save_db(&db);
            }
        }
        Some(Commands::Edit) => {
            let db = load_db();
            let content = serde_json::to_string_pretty(&db).unwrap();
            let mut file = File::create(get_db_path()).expect("Failed to create database");
            file.write_all(content.as_bytes()).expect("Failed to write database");
            eprintln!("Database saved to {}", get_db_path().display());
        }
        Some(Commands::Import { from, path, merge }) => {
            eprintln!("Import not implemented");
            process::exit(1);
        }
        Some(Commands::Init { shell, no_cmd, cmd, hook }) => {
            let output = match shell {
                Shell::Bash => init_bash(&cmd, &hook, no_cmd),
                Shell::Elvish => init_elvish(&cmd, &hook, no_cmd),
                Shell::Fish => init_fish(&cmd, &hook, no_cmd),
                Shell::Nushell => init_nushell(&cmd, &hook, no_cmd),
                Shell::Posix => init_posix(&cmd, &hook, no_cmd),
                Shell::Powershell => init_powershell(&cmd, &hook, no_cmd),
                Shell::Tcsh => init_tcsh(&cmd, &hook, no_cmd),
                Shell::Xonsh => init_xonsh(&cmd, &hook, no_cmd),
                Shell::Zsh => init_zsh(&cmd, &hook, no_cmd),
            };
            println!("{}", output);
        }
        Some(Commands::Query { all, interactive, list, score, exclude, base_dir, keywords }) => {
            let db = load_db();
            let cwd = env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
            let exclude_dirs = env::var("_ZO_EXCLUDE_DIRS")
                .unwrap_or_else(|_| "$HOME".to_string())
                .split(':')
                .map(|s| s.trim())
                .filter(|s| !s.is_empty())
                .collect::<Vec<_>>();
            let exclude_paths: Vec<String> = if exclude.is_some() {
                vec![canonicalize_path(&cwd.to_string_lossy()).to_string()]
            } else {
                exclude_dirs.iter().map(|d| {
                    if d.starts_with('$') {
                        d.to_string()
                    } else {
                        canonicalize_path(d).to_string()
                    }
                }).collect()
            };
            let mut results: Vec<(String, f64)> = db.entries.iter()
                .filter(|(_, e)| {
                    if exclude_paths.iter().any(|ep| e.path.starts_with(ep)) {
                        return false;
                    }
                    true
                })
                .map(|(path, entry)| {
                    let score = get_score(entry);
                    (path.clone(), score)
                })
                .collect();
            results.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
            if interactive {
                eprintln!("Interactive mode not fully implemented");
            } else if list {
                for (path, _) in results {
                    eprintln!("{}", path);
                }
            } else if score {
                for (path, s) in results {
                    eprintln!("{} {:.2}", path, s);
                }
            } else {
                if results.is_empty() {
                    eprintln!("No matching directories");
                    process::exit(1);
                }
                let best = &results[0];
                eprintln!("{}", best.0);
            }
        }
        Some(Commands::Remove { paths }) => {
            let mut db = load_db();
            for path in paths {
                let canonical = canonicalize_path(&path);
                db.entries.remove(&canonical);
            }
            save_db(&db);
        }
        None => {
            if cli.help {
                println!("{}", Cli::into_app().render_help().unwrap());
            } else if cli.version {
                println!("{} {}", env!("CARGO_PKG_NAME"), VERSION);
            }
        }
    }
}
