                Shell::Tcsh => init_tcsh(&cmd, &hook, no_cmd),
                Shell::Xonsh => init_xonsh(&cmd, &hook, no_cmd),
                Shell::Zsh => init_zsh(&cmd, &hook, no_cmd),
            };
