                    }
                }).collect()
            };
            let mut results: Vec<(String, f64)> = db.entries.iter()
                .filter(|(_, e)| {
                    if exclude_paths.iter().any(|ep| e.path.starts_with(ep)) {
                        return false;
                    }
                    true
                })
                .map(|(path, entry)| {
                    let score = get_score(entry);
                    (path.clone(), score)
                })
                .collect();
            results.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
            if interactive {
