        xdg_data_home.into()
    }
}

fn get_db_path() -> PathBuf {
    get_data_dir().join("zoxide.db")
}

fn load_db() -> Database {
    let db_path = get_db_path();
    if !db_path.exists() {
        return Database { entries: HashMap::new() };
    }
    let file = File::open(&db_path).expect("Failed to open database");
    let reader = BufReader::new(file);
    let content: String = reader.lines().collect::<Result<Vec<_>, _>>().unwrap_or_default().join("\n");
    if content.is_empty() {
        return Database { entries: HashMap::new() };
    }
    serde_json::from_str(&content).unwrap_or_else(|_| Database { entries: HashMap::new() })
}

fn save_db(db: &Database) {
    let db_path = get_db_path();
    let content = serde_json::to_string_pretty(db).unwrap();
    let mut file = File::create(&db_path).expect("Failed to create database");
    file.write_all(content.as_bytes()).expect("Failed to write database");
}

fn get_timestamp() -> u64 {
    SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_else(|_| std::time::Duration::from_secs(0)).as_secs()
}

fn get_score(entry: &Entry) -> f64 {
    let now = get_timestamp();
    let age = now - entry.last_accessed;
    entry.score * (1.0 + 0.0001 * age)
}

fn normalize_path(path: &str) -> String {
    let path = path.trim();
    if path.starts_with('/') {
        path.to_string()
    } else {
        format!("/{}", path)
    }
}

fn canonicalize_path(path: &str) -> String {
    let path = Path::new(path);
    if path.is_absolute() {
        path.to_string_lossy().to_string()
    } else {
        let cwd = env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
        cwd.join(path).to_string_lossy().to_string()
    }
}

fn is_directory(path: &str) -> bool {
    let path = Path::new(path);
    if path.is_absolute() {
        path.is_dir()
    } else {
        let cwd = env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
        cwd.join(path).is_dir()
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() > 1 && (args[1] == "--help" || args[1] == "-h") {
        print_help();
        return;
    }

    if args.len() > 1 && (args[1] == "--version" || args[1] == "-V") {
        println!("{} {}", env!("CARGO_PKG_NAME"), VERSION);
        return;
    }

    let command = if args.len() > 1 {
        &args[1]
    } else {
        print_help();
        return;
    };

    match command.as_str() {
        "add" => handle_add(&args[2..]),
        "edit" => handle_edit(),
        "import" => handle_import(&args[2..]),
        "init" => handle_init(&args[2..]),
        "query" => handle_query(&args[2..]),
        "remove" => handle_remove(&args[2..]),
        _ => {
            print_help();
        }
    }
}

fn print_help() {
    println!("Usage: zoxide <command> [options]");
    println!();
    println!("Commands:");
    println!("  add [OPTIONS]... <PATHS>...  Add directories to the database");
    println!("  edit                         Edit the database");
    println!("  import [OPTIONS] <PATH>      Import from another database");
    println!("  init [OPTIONS] <SHELL>       Initialize shell integration");
    println!("  query [OPTIONS]...           Query the database");
    println!("  remove [PATHS]...            Remove directories from the database");
    println!();
    println!("Options:");
    println!("  -h, --help       Print help information");
    println!("  -V, --version    Print version information");
}

fn handle_add(args: &[String]) {
    let mut score = None;
    let mut paths = Vec::new();

    let mut i = 0;
    while i < args.len() {
        if args[i] == "-s" || args[i] == "--score" {
            if i + 1 < args.len() {
                score = Some(args[i + 1].parse::<f64>().unwrap_or(0.0));
                i += 2;
            } else {
                eprintln!("error: --score requires a value");
                process::exit(1);
            }
        } else {
            paths.push(args[i].clone());
            i += 1;
        }
    }

    if paths.is_empty() {
        eprintln!("error: no paths specified");
        process::exit(1);
    }

    for path in &paths {
        let normalized = normalize_path(path);
        let canonical = canonicalize_path(&normalized);
        if !is_directory(&canonical) {
            eprintln!("error: {} is not a directory", canonical);
            process::exit(1);
        }
        let db = load_db();
        let entry = db.entries.get(&canonical).cloned().unwrap_or_else(|| {
            Entry {
                path: canonical.clone(),
                score: 0.0,
                last_accessed: get_timestamp(),
            }
        });
        let new_score = score.unwrap_or_else(|| get_score(&entry));
        let mut new_entry = entry;
        new_entry.score = new_score;
        new_entry.last_accessed = get_timestamp();
        db.entries.insert(canonical, new_entry);
        save_db(&db);
    }
}

fn handle_edit() {
    let db = load_db();
    let content = serde_json::to_string_pretty(&db).unwrap();
    let mut file = File::create(get_db_path()).expect("Failed to create database");
    file.write_all(content.as_bytes()).expect("Failed to write database");
    eprintln!("Database saved to {}", get_db_path().display());
}

fn handle_import(args: &[String]) {
    eprintln!("Import not implemented");
