fn handle_query(args: &[String]) {
    let mut all = false;
    let mut interactive = false;
    let mut list = false;
    let mut score = false;
    let mut exclude: Option<String> = None;
    let mut base_dir: Option<String> = None;
    let mut keywords = Vec::new();

    let mut i = 0;
    while i < args.len() {
        if args[i] == "-a" || args[i] == "--all" {
            all = true;
            i += 1;
        } else if args[i] == "-i" || args[i] == "--interactive" {
            interactive = true;
            i += 1;
        } else if args[i] == "-l" || args[i] == "--list" {
            list = true;
            i += 1;
        } else if args[i] == "-s" || args[i] == "--score" {
            score = true;
            i += 1;
        } else if args[i] == "--exclude" {
            if i + 1 < args.len() {
                exclude = Some(args[i + 1].clone());
                i += 2;
            } else {
                eprintln!("error: --exclude requires a value");
                process::exit(1);
            }
        } else if args[i] == "--base-dir" {
            if i + 1 < args.len() {
                base_dir = Some(args[i + 1].clone());
                i += 2;
            } else {
                eprintln!("error: --base-dir requires a value");
                process::exit(1);
            }
        } else {
            keywords.push(args[i].clone());
            i += 1;
        }
    }

    let db = load_db();
    let cwd = env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    let exclude_dirs = env::var("_ZO_EXCLUDE_DIRS")
        .unwrap_or_else(|_| "$HOME".to_string())
        .split(':')
        .map(|s| s.trim())
        .filter(|s| !s.is_empty())
        .collect::<Vec<_>>();
    let exclude_paths: Vec<String> = if exclude.is_some() {
        vec![canonicalize_path(&cwd.to_string_lossy()).to_string()]
    } else {
        exclude_dirs.iter().map(|d| {
            if d.starts_with('$') {
                d.to_string()
            } else {
                canonicalize_path(d).to_string()
            }
        }).collect()
    };
    let mut results: Vec<(String, f64)> = db.entries.iter()
        .filter(|(_, e)| {
            if exclude_paths.iter().any(|ep| e.path.starts_with(ep)) {
                return false;
            }
            true
        })
        .map(|(path, entry)| {
            let score = get_score(entry);
            (path.clone(), score)
        })
        .collect();
    results.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));

    if interactive {
        eprintln!("Interactive mode not fully implemented");
    } else if list {
        for (path, _) in results {
            eprintln!("{}", path);
        }
    } else if score {
        for (path, s) in results {
            eprintln!("{} {:.2}", path, s);
        }
    } else {
        if results.is_empty() {
            eprintln!("No matching directories");
            process::exit(1);
        }
        let best = &results[0];
        eprintln!("{}", best.0);
    }
}

fn handle_remove(args: &[String]) {
    let mut db = load_db();
    for path in args {
        let canonical = canonicalize_path(path);
        db.entries.remove(&canonical);
    }
    save_db(&db);
}
