    } else {
        match args[0].as_str() {
            "bash" => Shell::Bash,
            "zsh" => Shell::Zsh,
            "fish" => Shell::Fish,
            "posix" => Shell::Posix,
            "powershell" => Shell::PowerShell,
            "elvish" => Shell::Elvish,
