fn cmd_query(args: &[String]) -> Result<(), String> {
    let query = if args.is_empty() {
        String::new()
    } else {
        args.join(" ")
    };

    let entries = load_db()?;
    let mut results: Vec<_> = entries
        .iter()
        .filter(|(_, e)| {
            if query.is_empty() {
                return true;
            }
            let q = query.to_lowercase();
            e.path.to_lowercase().contains(&q)
        })
        .collect();

    if results.is_empty() {
        return Ok(());
    }

    // Sort by score (descending), then by age (descending)
    results.sort_by(|a, b| {
        let score_cmp = b.1.score.partial_cmp(&a.1.score).unwrap_or(std::cmp::Ordering::Equal);
        if score_cmp == std::cmp::Ordering::Equal {
            b.1.age.cmp(&a.1.age)
        } else {
            score_cmp
        }
    });

    let best = &results[0];
    println!("{}", best.0);
    Ok(())
}

fn cmd_remove(args: &[String]) -> Result<(), String> {
    let path = if args.is_empty() {
        return Err("zoxide: path is required".to_string());
    } else {
        args[0].clone()
    };

    let entries = load_db()?;
    if !entries.contains_key(&path) {
        return Err(format!("zoxide: {} not found in database", path));
    }

    let mut new_entries = entries;
    new_entries.remove(&path);
    save_db(&new_entries)?;
    Ok(())
}
RUSTEOF"}

