use std::collections::BTreeMap;
use std::env;
use std::fs::{self, File};
use std::io::{BufRead, BufReader, BufWriter, Write};
use std::path::PathBuf;
use std::process;

const VERSION: &str = "0.9.9";
const DEFAULT_MAXAGE: u64 = 10000;

#[derive(Debug, Clone)]
struct Entry {
    path: String,
    score: f64,
    age: u64,
}

#[derive(Debug, Clone, PartialEq)]
enum Hook {
    None,
    Pwd,
    Prompt,
}

#[derive(Debug, Clone, PartialEq)]
enum Shell {
    Bash,
    Zsh,
    Fish,
    Posix,
    PowerShell,
    Elvish,
    Nushell,
}

fn main() {
    let args: Vec<String> = env::args().collect();

    if let Err(e) = run(&args) {
        eprintln!("{}", e);
        process::exit(1);
    }
}

fn run(args: &[String]) -> Result<(), String> {
    let _cmd = args[1].clone();
    let mut subcmd = args[1].clone();

    if args.len() > 2 {
        subcmd = args[2].clone();
    }

    match subcmd.as_str() {
        "--help" | "-h" => Ok(print_help()),
        "--version" | "-V" => Ok(println!("zoxide {}", VERSION)),
        "add" => cmd_add(&args[1..]),
        "edit" => cmd_edit(),
        "import" => cmd_import(&args[1..]),
        "init" => cmd_init(&args[1..]),
        "query" => cmd_query(&args[1..]),
        "remove" => cmd_remove(&args[1..]),
        _ => {
            if args.len() == 1 {
                Ok(print_help())
            } else {
                Err(format!("zoxide: unrecognized command '{}'", subcmd))
            }
        }
    }
}

