    builtin local results
    results="$(command zoxide query -- "$cur")"
    if [[ -n "${{results}}" ]]; then
        builtin COMPREPLY=("${{results[@]/#/$__zoxide_z_prefix}}")
    fi
}}
__zoxide_z_complete_helper() {{
    builtin local cur="${{COMP_WORDS[COMP_CWORD]}}"
    builtin local results
    results="$(command zoxide query -- "$cur")"
    if [[ -n "${{results}}" ]]; then
        builtin COMPREPLY=("${{results[@]/#/$__zoxide_z_prefix}}")
    fi
    builtin printf '\e[5n' > /dev/tty
}}
builtin complete -F __zoxide_z_complete -o filenames -- {}
builtin complete -r zi >/dev/null || builtin true
"#.to_string()
    );

    let doctor_func = r#"
__zoxide_doctor() {
    [[ ${{_ZO_DOCTOR:-1} -ne 0 }] || return 0
    [[ ${{chpwd_functions[(Ie)__zoxide_hook]:-} -eq 0 }] || return 0
    _ZO_DOCTOR=0
    builtin printf '%s\n' \
        'zoxide: detected a possible configuration issue.' \
        'Please ensure that zoxide is initialized right at the end of your shell configuration file (usually ~/.bashrc).' \
        '' \
        'If the issue persists, consider filing an issue at:' \
        'https://github.com/ajeetdsouza/zoxide/issues' \
    return 0
}
"#.to_string();

    let init_comment = format!(
        r#"
# =============================================================================
#
# Utility functions for zoxide.
#
"#.to_string()
