fn cmd_query(args: &[String]) -> Result<(), String> {
    let query = if args.is_empty() {
        String::new()
    } else {
        args.join(" ")
    };

    let entries = load_db()?;
    let mut results: Vec<_> = entries
        .iter()
        .filter(|(_, e)| {
            if query.is_empty() {
                return true;
            }
            let q = query.to_lowercase();
